-- SOURCE parent_access.sql sha256=e6e46dda5a4dc19aeeef64846d99b4db1774a6b78839920952dc63e28daa9f13
-- Return an active, tenant-verified parent and verify its full ancestry.
CREATE FUNCTION public.academic_structure_parent(p_entity text, p_id uuid, p_institution uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE result jsonb; id_column text;
BEGIN
    CASE p_entity
    WHEN 'departments' THEN id_column:='department_id';
    WHEN 'programs' THEN id_column:='program_id';
    WHEN 'academic_years' THEN id_column:='academic_year_id';
    WHEN 'semesters' THEN id_column:='semester_id';
    WHEN 'courses' THEN id_column:='course_id';
    WHEN 'program_semesters' THEN id_column:='program_semester_id';
    WHEN 'curriculum_versions' THEN id_column:='curriculum_version_id';
    WHEN 'curriculum_subjects' THEN id_column:='curriculum_subject_id';
    WHEN 'admission_cohorts' THEN id_column:='admission_cohort_id';
    WHEN 'academic_sections' THEN id_column:='academic_section_id';
    ELSE RAISE EXCEPTION 'Unsupported parent' USING ERRCODE='22023';
    END CASE;
    IF p_entity IN ('departments','programs','academic_years','semesters','courses') THEN
        IF public.academic_master_tenant(p_entity,p_id) IS DISTINCT FROM p_institution THEN
            RAISE EXCEPTION 'Academic parent not found' USING ERRCODE='P0002';
        END IF;
        EXECUTE format('SELECT to_jsonb(t) FROM public.%I t WHERE %I=$1',p_entity,id_column) INTO result USING p_id;
    ELSE
        EXECUTE format('SELECT to_jsonb(t) FROM public.%I t WHERE %I=$1 AND institution_id=$2',p_entity,id_column)
            INTO result USING p_id,p_institution;
    END IF;
    IF result IS NULL THEN RAISE EXCEPTION 'Academic parent not found' USING ERRCODE='P0002'; END IF;
    IF NOT (result->>'is_active')::boolean THEN
        RAISE EXCEPTION 'Active academic ancestry required' USING ERRCODE='23514';
    END IF;
    CASE p_entity
    WHEN 'programs','courses' THEN
        PERFORM public.academic_structure_parent('departments',(result->>'department_id')::uuid,p_institution);
    WHEN 'semesters' THEN
        PERFORM public.academic_structure_parent('academic_years',(result->>'academic_year_id')::uuid,p_institution);
    WHEN 'program_semesters','curriculum_versions','admission_cohorts' THEN
        PERFORM public.academic_structure_parent('programs',(result->>'program_id')::uuid,p_institution);
        IF p_entity<>'program_semesters' THEN
            PERFORM public.academic_structure_parent('academic_years',(result->>'academic_year_id')::uuid,p_institution);
        END IF;
        IF p_entity='admission_cohorts' THEN
            PERFORM public.academic_structure_parent('curriculum_versions',(result->>'curriculum_version_id')::uuid,p_institution);
        END IF;
    WHEN 'curriculum_subjects' THEN
        PERFORM public.academic_structure_parent('curriculum_versions',(result->>'curriculum_version_id')::uuid,p_institution);
        PERFORM public.academic_structure_parent('program_semesters',(result->>'program_semester_id')::uuid,p_institution);
        PERFORM public.academic_structure_parent('courses',(result->>'course_id')::uuid,p_institution);
    WHEN 'academic_sections' THEN
        PERFORM public.academic_structure_parent('admission_cohorts',(result->>'admission_cohort_id')::uuid,p_institution);
        PERFORM public.academic_structure_parent('program_semesters',(result->>'program_semester_id')::uuid,p_institution);
        PERFORM public.academic_structure_parent('semesters',(result->>'semester_id')::uuid,p_institution);
    ELSE NULL;
    END CASE;
    RETURN result;
END;
$$;

-- SOURCE relationships.sql sha256=4410a948003fd72623b201bcd649727758d034e67d0a227351dd1babf7cf9fc5
CREATE FUNCTION public.validate_academic_structure_relationships() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE item jsonb:=to_jsonb(NEW); parent jsonb; stage jsonb; cohort jsonb; section jsonb; active boolean;
BEGIN
    active:=CASE WHEN TG_TABLE_NAME='admission_cohorts' THEN item->>'status'='active' ELSE (item->>'is_active')::boolean END;
    -- Metadata edits and deactivation remain possible after parent deactivation.
    IF TG_OP='UPDATE' AND (NOT active OR (OLD.is_active AND NOT
        (TG_TABLE_NAME='curriculum_versions' AND item->>'status'='published' AND to_jsonb(OLD)->>'status'='draft')))
    THEN RETURN NEW; END IF;
    CASE TG_TABLE_NAME
    WHEN 'program_semesters' THEN
        PERFORM public.academic_structure_parent('programs',NEW.program_id,NEW.institution_id);
    WHEN 'curriculum_versions' THEN
        PERFORM public.academic_structure_parent('programs',NEW.program_id,NEW.institution_id);
        PERFORM public.academic_structure_parent('academic_years',NEW.academic_year_id,NEW.institution_id);
    WHEN 'curriculum_subjects' THEN
        parent:=public.academic_structure_parent('curriculum_versions',NEW.curriculum_version_id,NEW.institution_id);
        stage:=public.academic_structure_parent('program_semesters',NEW.program_semester_id,NEW.institution_id);
        PERFORM public.academic_structure_parent('courses',NEW.course_id,NEW.institution_id);
        IF parent->>'program_id' IS DISTINCT FROM stage->>'program_id'
           OR (stage->>'semester_number')::integer>(parent->>'total_semesters')::integer THEN
            RAISE EXCEPTION 'Curriculum and program semester must match' USING ERRCODE='23514';
        END IF;
    WHEN 'admission_cohorts' THEN
        PERFORM public.academic_structure_parent('programs',NEW.program_id,NEW.institution_id);
        PERFORM public.academic_structure_parent('academic_years',NEW.academic_year_id,NEW.institution_id);
        parent:=public.academic_structure_parent('curriculum_versions',NEW.curriculum_version_id,NEW.institution_id);
        IF parent->>'program_id' IS DISTINCT FROM NEW.program_id::text
           OR (TG_OP='INSERT' AND parent->>'status'<>'published') THEN
            RAISE EXCEPTION 'Matching published curriculum required' USING ERRCODE='23514';
        END IF;
    WHEN 'academic_sections' THEN
        cohort:=public.academic_structure_parent('admission_cohorts',NEW.admission_cohort_id,NEW.institution_id);
        stage:=public.academic_structure_parent('program_semesters',NEW.program_semester_id,NEW.institution_id);
        parent:=public.academic_structure_parent('curriculum_versions',(cohort->>'curriculum_version_id')::uuid,NEW.institution_id);
        PERFORM public.academic_structure_parent('semesters',NEW.semester_id,NEW.institution_id);
        IF cohort->>'program_id' IS DISTINCT FROM stage->>'program_id'
           OR (stage->>'semester_number')::integer>(parent->>'total_semesters')::integer THEN
            RAISE EXCEPTION 'Section must use its cohort program' USING ERRCODE='23514';
        END IF;
    WHEN 'academic_offerings' THEN
        section:=public.academic_structure_parent('academic_sections',NEW.academic_section_id,NEW.institution_id);
        parent:=public.academic_structure_parent('curriculum_subjects',NEW.curriculum_subject_id,NEW.institution_id);
        cohort:=public.academic_structure_parent('admission_cohorts',(section->>'admission_cohort_id')::uuid,NEW.institution_id);
        IF parent->>'curriculum_version_id' IS DISTINCT FROM cohort->>'curriculum_version_id'
           OR parent->>'program_semester_id' IS DISTINCT FROM section->>'program_semester_id' THEN
            RAISE EXCEPTION 'Offering must match section semester and assigned curriculum' USING ERRCODE='23514';
        END IF;
    END CASE;
    RETURN NEW;
END;
$$;

-- SOURCE lifecycle.sql sha256=8a3e515586e6890c3ca474f24b7ae11b0bcc104204d193a5d9c34cd754154837
CREATE FUNCTION public.validate_academic_structure_lifecycle() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE item jsonb:=to_jsonb(NEW); parent_status text; mapping record;
BEGIN
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('academic-setup:'||NEW.institution_id::text,0));
    -- Before triggers cannot read a stored generated column's value.
    IF TG_TABLE_NAME='admission_cohorts' THEN
        item:=item||jsonb_build_object('is_active',NEW.status='active');
    END IF;
    IF item ? 'name' THEN item:=item||jsonb_build_object('name',btrim(item->>'name')); END IF;
    IF item ? 'code' THEN item:=item||jsonb_build_object('code',btrim(item->>'code')); END IF;
    IF item ? 'version' THEN item:=item||jsonb_build_object('version',btrim(item->>'version')); END IF;
    IF TG_TABLE_NAME='curriculum_subjects' THEN
        SELECT status INTO parent_status FROM public.curriculum_versions
          WHERE curriculum_version_id=NEW.curriculum_version_id AND institution_id=NEW.institution_id;
        IF parent_status IS DISTINCT FROM 'draft' THEN
            RAISE EXCEPTION 'Published curriculum mappings are immutable' USING ERRCODE='23514';
        END IF;
    END IF;
    IF TG_TABLE_NAME='curriculum_versions' THEN
        IF TG_OP='INSERT' AND NEW.status<>'draft' THEN
            RAISE EXCEPTION 'Create a draft before publishing' USING ERRCODE='23514';
        END IF;
        IF TG_OP='UPDATE' THEN
            IF OLD.status<>'draft' AND (
                (to_jsonb(OLD)-ARRAY['status','is_active','updated_at']) IS DISTINCT FROM
                (item-ARRAY['status','is_active','updated_at'])
                OR NEW.status='draft' OR (OLD.status='archived' AND NEW.status<>'archived')) THEN
                RAISE EXCEPTION 'Published curriculum versions are immutable' USING ERRCODE='23514';
            END IF;
            IF OLD.status='draft' AND NEW.status='archived' THEN
                RAISE EXCEPTION 'Only published curricula can be archived' USING ERRCODE='23514';
            END IF;
            IF OLD.status='draft' AND NEW.status='published' THEN
                IF NOT NEW.is_active OR NOT EXISTS(SELECT 1 FROM public.curriculum_subjects
                    WHERE curriculum_version_id=NEW.curriculum_version_id AND is_active) THEN
                    RAISE EXCEPTION 'An active mapped subject is required before publication' USING ERRCODE='23514';
                END IF;
                FOR mapping IN SELECT curriculum_subject_id FROM public.curriculum_subjects
                    WHERE curriculum_version_id=NEW.curriculum_version_id AND is_active LOOP
                    PERFORM public.academic_structure_parent('curriculum_subjects',mapping.curriculum_subject_id,NEW.institution_id);
                END LOOP;
                item:=item||jsonb_build_object('published_at',now());
                -- Freeze subject metadata so a published curriculum keeps its historical meaning
                -- even if the live course record is edited later.
                UPDATE public.curriculum_subjects
                SET subject_code = c.code,
                    subject_name = btrim(c.name),
                    credits = c.credits,
                    lecture_hours = c.lecture_hours,
                    tutorial_hours = c.tutorial_hours,
                    practical_hours = c.practical_hours
                FROM public.courses c
                WHERE curriculum_subjects.curriculum_version_id = NEW.curriculum_version_id
                  AND curriculum_subjects.course_id = c.course_id
                  AND curriculum_subjects.institution_id = NEW.institution_id;
            END IF;
        END IF;
    END IF;
    item:=item||jsonb_build_object('updated_at',now());
    -- Exclude generated cohort field when rebuilding NEW.
    IF TG_TABLE_NAME='admission_cohorts' THEN item:=item-'is_active'; END IF;
    NEW:=jsonb_populate_record(NEW,item);
    RETURN NEW;
END;
$$;

-- SOURCE write.sql sha256=9dc8a388c1315edb5ddc59b72a62d77c5c8be47d501128f66413bc801f08f33c
CREATE FUNCTION public.manage_academic_structure_record(
    p_actor_user_id uuid, p_institution_id uuid, p_entity text, p_record_id uuid, p_payload jsonb
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE id_column text; resource text; allowed text[]; mutable text[]; key text;
    before_row jsonb; after_row jsonb; item jsonb; item_id uuid:=COALESCE(p_record_id,gen_random_uuid());
    columns text; expressions text;
BEGIN
    CASE p_entity
    WHEN 'program_semesters' THEN
        id_column:='program_semester_id'; resource:='departments';
        allowed:=ARRAY['program_id','name','code','semester_number','is_active'];
        mutable:=ARRAY['name','code','is_active'];
    WHEN 'curriculum_versions' THEN
        id_column:='curriculum_version_id'; resource:='courses';
        allowed:=ARRAY['program_id','academic_year_id','name','version','total_semesters','description','is_active'];
        mutable:=ARRAY['name','description','status','is_active'];
    WHEN 'curriculum_subjects' THEN
        id_column:='curriculum_subject_id'; resource:='courses';
        allowed:=ARRAY['curriculum_version_id','program_semester_id','course_id','course_type','is_required','is_active'];
        mutable:=ARRAY['course_type','is_required','is_active'];
    WHEN 'admission_cohorts' THEN
        id_column:='admission_cohort_id'; resource:='departments';
        allowed:=ARRAY['program_id','curriculum_version_id','academic_year_id','name','code','start_year','end_year','expected_count','description','status'];
        mutable:=ARRAY['name','code','expected_count','description','status'];
    WHEN 'academic_sections' THEN
        id_column:='academic_section_id'; resource:='courses';
        allowed:=ARRAY['admission_cohort_id','program_semester_id','semester_id','name','code','capacity','description','is_active'];
        mutable:=ARRAY['name','capacity','description','is_active'];
    WHEN 'academic_offerings' THEN
        id_column:='academic_offering_id'; resource:='courses';
        allowed:=ARRAY['academic_section_id','curriculum_subject_id','capacity','is_active'];
        mutable:=ARRAY['capacity','is_active'];
    ELSE RAISE EXCEPTION 'Unknown academic entity' USING ERRCODE='22023';
    END CASE;
    PERFORM public.assert_academic_foundation_actor(p_actor_user_id,p_institution_id,resource);
    IF p_payload IS NULL OR jsonb_typeof(p_payload)<>'object' OR p_payload='{}'::jsonb THEN
        RAISE EXCEPTION 'Academic fields required' USING ERRCODE='22023';
    END IF;
    FOR key IN SELECT jsonb_object_keys(p_payload) LOOP
        IF NOT key=ANY(CASE WHEN p_record_id IS NULL THEN allowed ELSE mutable END) THEN
            RAISE EXCEPTION 'Unsupported or immutable academic field' USING ERRCODE='22023';
        END IF;
    END LOOP;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('academic-setup:'||p_institution_id::text,0));
    IF p_record_id IS NOT NULL THEN
        EXECUTE format('SELECT to_jsonb(t) FROM public.%I t WHERE %I=$1 AND institution_id=$2 FOR UPDATE',p_entity,id_column)
            INTO before_row USING p_record_id,p_institution_id;
        IF before_row IS NULL THEN RAISE EXCEPTION 'Academic record not found' USING ERRCODE='P0002'; END IF;
    END IF;
    item:=COALESCE(before_row,'{}'::jsonb)||p_payload||jsonb_build_object(id_column,item_id,'institution_id',p_institution_id);
    SELECT string_agg(format('%I',field),','),string_agg(format('r.%I',field),',') INTO columns,expressions
      FROM jsonb_object_keys(CASE WHEN p_record_id IS NULL THEN item ELSE p_payload END) AS field;
    IF p_record_id IS NULL THEN
        EXECUTE format('INSERT INTO public.%I AS t (%s) SELECT %s FROM jsonb_populate_record(NULL::public.%I,$1) r RETURNING to_jsonb(t)',p_entity,columns,expressions,p_entity)
            INTO after_row USING item;
    ELSE
        EXECUTE format('UPDATE public.%I AS t SET (%s)=(SELECT %s FROM jsonb_populate_record(NULL::public.%I,$1) r) WHERE %I=$2 AND institution_id=$3 RETURNING to_jsonb(t)',p_entity,columns,expressions,p_entity,id_column)
            INTO after_row USING item,p_record_id,p_institution_id;
    END IF;
    INSERT INTO public.admin_audit_log(actor_user_id,institution_id,action,table_name,record_id,record_data)
    VALUES(p_actor_user_id,p_institution_id,'academic.'||p_entity||CASE WHEN p_record_id IS NULL THEN '.create' ELSE '.update' END,
        p_entity,item_id::text,jsonb_build_object('before',before_row,'after',after_row));
    RETURN after_row;
END;
$$;

-- SOURCE parent_guards.sql sha256=ccb53484d2a896e339250dc8e73b0fa783f0479638fa0719e2607b250f9eed14
-- Extend the existing guard without replacing it or weakening its old checks.
CREATE FUNCTION public.guard_academic_workspace_parent() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE blocked boolean:=false; item jsonb:=to_jsonb(NEW); tenant uuid;
BEGIN
    IF TG_TABLE_NAME='admission_cohorts' THEN
        IF NEW.status='active' OR OLD.status<>'active' THEN RETURN NEW; END IF;
    ELSIF NEW.is_active OR NOT OLD.is_active THEN RETURN NEW;
    END IF;
    IF TG_TABLE_NAME IN ('programs','courses','academic_years','semesters') THEN
        tenant:=public.academic_master_tenant(TG_TABLE_NAME,(to_jsonb(OLD)->>TG_ARGV[0])::uuid);
    ELSE tenant:=(item->>'institution_id')::uuid;
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('academic-setup:'||tenant::text,0));
    CASE TG_TABLE_NAME
    WHEN 'programs' THEN
        blocked:=EXISTS(SELECT 1 FROM public.program_semesters WHERE program_id=OLD.program_id AND is_active)
            OR EXISTS(SELECT 1 FROM public.curriculum_versions WHERE program_id=OLD.program_id AND is_active)
            OR EXISTS(SELECT 1 FROM public.admission_cohorts WHERE program_id=OLD.program_id AND is_active);
    WHEN 'courses' THEN
        blocked:=EXISTS(SELECT 1 FROM public.curriculum_subjects WHERE course_id=OLD.course_id AND is_active);
    WHEN 'academic_years' THEN
        blocked:=EXISTS(SELECT 1 FROM public.curriculum_versions WHERE academic_year_id=OLD.academic_year_id AND is_active)
            OR EXISTS(SELECT 1 FROM public.admission_cohorts WHERE academic_year_id=OLD.academic_year_id AND is_active);
    WHEN 'semesters' THEN
        blocked:=EXISTS(SELECT 1 FROM public.academic_sections WHERE semester_id=OLD.semester_id AND is_active);
    WHEN 'program_semesters' THEN
        blocked:=EXISTS(SELECT 1 FROM public.curriculum_subjects WHERE program_semester_id=OLD.program_semester_id AND is_active)
            OR EXISTS(SELECT 1 FROM public.academic_sections WHERE program_semester_id=OLD.program_semester_id AND is_active);
    WHEN 'curriculum_versions' THEN
        blocked:=EXISTS(SELECT 1 FROM public.admission_cohorts WHERE curriculum_version_id=OLD.curriculum_version_id AND is_active)
            OR EXISTS(SELECT 1 FROM public.curriculum_subjects WHERE curriculum_version_id=OLD.curriculum_version_id AND is_active);
    WHEN 'curriculum_subjects' THEN
        blocked:=EXISTS(SELECT 1 FROM public.academic_offerings WHERE curriculum_subject_id=OLD.curriculum_subject_id AND is_active);
    WHEN 'admission_cohorts' THEN
        blocked:=EXISTS(SELECT 1 FROM public.academic_sections WHERE admission_cohort_id=OLD.admission_cohort_id AND is_active);
    WHEN 'academic_sections' THEN
        blocked:=EXISTS(SELECT 1 FROM public.academic_offerings WHERE academic_section_id=OLD.academic_section_id AND is_active);
    ELSE NULL;
    END CASE;
    IF blocked THEN RAISE EXCEPTION 'Deactivate dependent academic records first' USING ERRCODE='23514'; END IF;
    RETURN NEW;
END;
$$;

-- SOURCE security.sql sha256=06206a618ebd41b9c47f6a453bc645cd1cf2d6517c54d55cf498b5b5ec307131
DO $$
DECLARE relation_name text; id_column text;
BEGIN
    FOREACH relation_name IN ARRAY ARRAY[
        'program_semesters','curriculum_versions','curriculum_subjects',
        'admission_cohorts','academic_sections','academic_offerings'
    ] LOOP
        id_column:=regexp_replace(relation_name,'s$','')||'_id';
        EXECUTE format('ALTER TABLE public.%I OWNER TO postgres',relation_name);
        EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',relation_name);
        EXECUTE format('REVOKE ALL ON TABLE public.%I FROM PUBLIC, anon, authenticated, service_role',relation_name);
        EXECUTE format('GRANT SELECT ON TABLE public.%I TO service_role',relation_name);
        EXECUTE format('CREATE TRIGGER structure_lifecycle BEFORE INSERT OR UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.validate_academic_structure_lifecycle()',relation_name);
        EXECUTE format('CREATE TRIGGER structure_relationships BEFORE INSERT OR UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.validate_academic_structure_relationships()',relation_name);
        EXECUTE format('CREATE TRIGGER structure_parent_guard BEFORE UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.guard_academic_workspace_parent(%L)',relation_name,id_column);
    END LOOP;
    FOREACH relation_name IN ARRAY ARRAY['programs','courses','academic_years','semesters'] LOOP
        id_column:=CASE relation_name WHEN 'academic_years' THEN 'academic_year_id'
            ELSE regexp_replace(relation_name,'s$','')||'_id' END;
        EXECUTE format('CREATE TRIGGER structure_parent_guard BEFORE UPDATE OF is_active ON public.%I FOR EACH ROW EXECUTE FUNCTION public.guard_academic_workspace_parent(%L)',relation_name,id_column);
    END LOOP;
END;
$$;
REVOKE ALL ON FUNCTION public.academic_structure_parent(text,uuid,uuid),
    public.validate_academic_structure_relationships(), public.validate_academic_structure_lifecycle(),
    public.guard_academic_workspace_parent(),
    public.manage_academic_structure_record(uuid,uuid,text,uuid,jsonb)
    FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.manage_academic_structure_record(uuid,uuid,text,uuid,jsonb) TO service_role;
NOTIFY pgrst,'reload schema';
COMMIT;
